mapper.select:
SELECT 
FROM merchant m JOIN merchant_store s ON s.merchant_id=m.id
WHERE m.id=#{merchantId} AND s.id=#{storeId} AND m.owner_user_id=#{ownerUserId}

mapper.update:
UPDATE merchant_member_invitation SET status='CANCELED',pending_marker=CAST(id AS CHAR),
  version=version+1,updated_at=#{now}
WHERE id=#{invitationId} AND merchant_id=#{merchantId} AND status='INVITED'
  AND version=#{expectedVersion}

UPDATE merchant_member_invitation SET status='CONFIRMED',confirmed_by=#{confirmedBy},
  member_id=#{memberId},pending_marker=CAST(id AS CHAR),version=version+1,updated_at=#{now}
WHERE id=#{invitationId} AND merchant_id=#{merchantId} AND status='INVITED'
  AND version=#{expectedVersion}

mapper.select:
SELECT  FROM merchant_member_invitation
WHERE merchant_id=#{merchantId} AND store_id=#{storeId}
ORDER BY id DESC LIMIT #{limit} OFFSET #{offset}

SELECT  FROM merchant_member_invitation
WHERE phone=#{phone}
ORDER BY id DESC LIMIT #{limit} OFFSET #{offset}

SELECT 
FROM merchant_member mb
LEFT JOIN merchant_member_store_grant g ON g.member_id=mb.id AND g.store_id=#{storeId}
WHERE mb.id=#{memberId} AND mb.merchant_id=#{merchantId}

mapper.sql:
FROM merchant_member mb
JOIN merchant_member_store_grant g ON g.member_id=mb.id AND g.store_id=#{storeId}
LEFT JOIN merchant_member_invitation inv ON inv.member_id=mb.id AND inv.status='CONFIRMED'
WHERE mb.merchant_id=#{merchantId}

mapper.select:
SELECT m.id AS merchantId,m.merchant_name AS merchantName,m.status AS merchantStatus,
  s.id AS storeId,s.store_name AS storeName,s.status AS storeStatus
FROM merchant m JOIN merchant_store s ON s.merchant_id=m.id AND s.id=#{storeId}
WHERE m.id=#{merchantId}
